import{_ as s,C as l,o as a,c as n,a2 as t,b as i,w as o,a as d,E as c,a3 as E}from"./chunks/framework.BBdhqAg0.js";const m=JSON.parse('{"title":"직원 인사 관리","description":"","frontmatter":{},"headers":[],"relativePath":"hr-manage/staff.md","filePath":"hr-manage/staff.md","lastUpdated":1793029965000}'),C={name:"hr-manage/staff.md"};function u(f,e,A,_,p,B){const r=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="직원-인사-관리" tabindex="-1">직원 인사 관리 <a class="header-anchor" href="#직원-인사-관리" aria-label="Permalink to &quot;직원 인사 관리&quot;">​</a></h1><blockquote><p><strong>직원 인사 관리</strong>는 임직원의 기초 인적 사항, 계정 연동, 고용 형태(정규직/계약직/위촉직 등)를 관리하고, 부서 발령·보직 이동·승진 등의 인사 이력을 영구적으로 기록·보관하는 모듈입니다.</p></blockquote><ul><li><strong>메뉴 위치</strong>: <code>본사 관리 &gt; 인사 조직 관리 &gt; 직원 인사 관리</code> (<code>/hr-manage/staff</code>, <code>executives</code>, <code>appointments</code>, <code>records</code>)</li><li><strong>관리 대상</strong>: 인사 담당자, 부서장, 시스템 관리자</li></ul>',3)),(a(),i(E,null,{default:o(()=>[c(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%91%A4%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EA%B3%84%EC%A0%95%3Cbr%3E(accounts.User)%22%5D%20%3C--%3E%20B%5B%22%F0%9F%A7%91%E2%80%8D%F0%9F%92%BC%20%EC%A7%81%EC%9B%90%20%EC%A0%95%EB%B3%B4%3Cbr%3E(company.Staff)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%8F%A2%20%EB%B3%B4%EC%A7%81%20%EB%B0%9C%EB%A0%B9%3Cbr%3E(StaffAssignment)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8B%20%EC%9D%B8%EC%82%AC%20%EC%9D%B4%EB%A0%A5%20%EB%8C%80%EC%9E%A5%3Cbr%3E(StaffRecord)%22%5D%0A%20%20%20%20B%20--%3E%20E%5B%22%F0%9F%93%91%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%20%26%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%B0%B8%EC%97%AC%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="_1-직원-정보-관리-staff" tabindex="-1">1. 직원 정보 관리 (Staff) <a class="header-anchor" href="#_1-직원-정보-관리-staff" aria-label="Permalink to &quot;1. 직원 정보 관리 (Staff)&quot;">​</a></h2><p>임직원의 기본 정보(성명, 생년월일, 연락처, 입사일, 재직 상태)를 등록하고 로그인 계정과 1:1 매핑합니다.</p><ul><li><strong>사용자 계정 매핑</strong>: 시스템 계정(<code>accounts.User</code>)과 직원 레코드를 연결하여 로그인 시 본인의 인사 정보, 휴가 현황, 결재 권한이 자동으로 동기화됩니다.</li><li><strong>고용 형태 세분화</strong>: 정규직, 계약직/기간제, 파견직, 위촉직/자문, 인턴/수습, 파트타임 등 고용 형태를 구분하여 관리하며, 계약직의 경우 계약 만료일을 추적할 수 있습니다.</li><li><strong>재직 상태 제어</strong>: <ul><li><code>재직</code>: 정상 근무 상태 (시스템 및 결재 권한 활성)</li><li><code>휴직</code>: 육아/질병 휴직 등 (업무 일시 중지)</li><li><code>퇴직신청 / 퇴직</code>: 퇴사일 지정 및 시스템 접근 권한 자동 차단</li></ul></li></ul><h2 id="_2-임원-정보-관리-executive" tabindex="-1">2. 임원 정보 관리 (Executive) <a class="header-anchor" href="#_2-임원-정보-관리-executive" aria-label="Permalink to &quot;2. 임원 정보 관리 (Executive)&quot;">​</a></h2><p>회사의 등기 임원 및 미등기 임원에 대한 직무 구분, 선임일, 임기 만료일, 주주총회/이사회 이력을 독립적으로 관리합니다.</p><ul><li><strong>임기 관리</strong>: 임원별 임기 시작일과 만료일을 기록하여 중임/퇴임 시점을 사전에 알림받을 수 있습니다.</li><li><strong>결재 전결 연동</strong>: 대표이사 및 담당 임원의 결재 전결 규정과 연동되어 고액 지출 및 중요 계약 품의 시 필수 심사선으로 지정됩니다.</li></ul><h2 id="_3-인사-발령-관리-appointments" tabindex="-1">3. 인사 발령 관리 (Appointments) <a class="header-anchor" href="#_3-인사-발령-관리-appointments" aria-label="Permalink to &quot;3. 인사 발령 관리 (Appointments)&quot;">​</a></h2><p>입사, 부서 이동, 전보, 승진, 겸직 등 조직 개편 및 인사이동 시 발령을 등록하고 적용합니다.</p><ul><li><strong>주보직(Primary) 및 겸직(Secondary) 지원</strong>: <ul><li>직원은 기본적으로 하나의 주보직을 가지며, 프로젝트 투입이나 태스크포스(TF) 등에 따른 겸직을 복수로 부여받을 수 있습니다.</li><li>전자결재 기안 시 상신 보직을 선택하여 결재선(본사 부서 결재 vs 프로젝트 결재)을 유연하게 전환할 수 있습니다.</li></ul></li><li><strong>발령 적용 시점</strong>: 발령 일자를 지정하여 정기 인사 시점에 맞추어 조직 및 결재선이 자동 갱신됩니다.</li></ul><h2 id="_4-인사-이력-관리-records" tabindex="-1">4. 인사 이력 관리 (Records) <a class="header-anchor" href="#_4-인사-이력-관리-records" aria-label="Permalink to &quot;4. 인사 이력 관리 (Records)&quot;">​</a></h2><p>입사부터 퇴사까지 임직원의 모든 신분 변동 내역(승진, 보직 변경, 포상, 징계, 휴직 등)을 시계열로 영구 보관합니다.</p><ul><li><strong>자동 이력 생성</strong>: 인사 발령이 승인되면 변경 전/후 부서, 직급, 직책 정보가 인사 이력 대장에 자동으로 스냅샷으로 기록됩니다.</li><li><strong>인사 기록 카드 출력</strong>: 필요 시 직원의 전체 재직 이력을 한눈에 볼 수 있는 인사 기록 카드로 조회 및 인쇄할 수 있습니다.</li></ul>',12))])}const h=s(C,[["render",u]]);export{m as __pageData,h as default};
